import type { MetadataRoute } from "next";

/**
 * Web app manifest (round 9, with the new brand mark). Next serves this at /manifest.webmanifest and adds the
 * <link rel="manifest"> itself, so nothing is needed in app/layout.tsx.
 *
 * The icons are the circular monogram on white, generated by scripts/make-icons.mjs; the full lockup is not legible
 * at launcher sizes. The theme colour matches the header band (--color-navy-950) and the viewport themeColor in
 * app/layout.tsx.
 */
export default function manifest(): MetadataRoute.Manifest {
  return {
    name: "AdamasTech Consulting",
    short_name: "AdamasTech",
    description: "Enterprise cloud, SAP, digital transformation and AI consulting.",
    start_url: "/",
    display: "standalone",
    background_color: "#ffffff",
    theme_color: "#000c33",
    icons: [
      { src: "/icon-192.png", sizes: "192x192", type: "image/png" },
      { src: "/icon-512.png", sizes: "512x512", type: "image/png" },
    ],
  };
}
